const res = $input.first().json;
const ents = Array.isArray(res.entries) ? res.entries : [];
const list = ents.map((e, i) => {
  const cat = (e.feed && e.feed.category && e.feed.category.title) || '-';
  const feed = (e.feed && e.feed.title) || '';
  return `${i + 1}. [${cat}] ${e.title} \u2014 ${feed}\n   ${e.url}`;
}).join('\n');

const GENERIC_SYS = `You are the reader's research chief of staff. Their detailed profile is injected at runtime. Given the list of articles the reader starred this week, produce concise markdown with exactly these sections:\n## Top 5 reads  (ranked, one line each: what it is + why it matters to their goals; pick from the list only)\n## 3 post angles  (each: a specific title, 2 bullet outline, which of their skills/assets it leverages; bias to weekend-sized)\n## Market signal  (one hiring / comp / tech-shift observation worth acting on)\n## Weekend lab project  (one <1 weekend project that would give interview-defensible depth)`;
const envS = ($env.CURATOR_DIGEST_PROFILE || '').trim();
const sys = envS.length > 40 ? envS : GENERIC_SYS;

const user = ents.length
  ? `Articles the reader starred this week (${ents.length}):\n\n${list}`
  : `Nothing was starred this week. Use the reader's standing themes from the profile above to still produce all four sections.`;

return [{ json: { sysPrompt: sys, userMsg: user, count: ents.length } }];
